Item.method_code:
const {
	itemType,
	itemTypeName,
	location
} = options;
const tooltipTemplate = target.tooltipTemplate || target.tooltip_template;
const itemTypeLabel = itemType.label || itemTypeName;
const newTooltipTemplate = tooltipTemplate.replace('{0}', itemTypeLabel);
const newLabel = target.label.replace('{0}', itemTypeLabel);
const openNewCommand = options.commandFactory('OpenNewItem', { itemType, itemTypeName, location });
const disabled = !openNewCommand.canExecute();

return {
	disabled,
	tooltipTemplate,
	tooltip_template: newTooltipTemplate,
	label: newLabel
};
